// 1b（2026-06-12）— 群读写经 getGroupsBackend() 抽象：SF_GROUPS_BACKEND==='node'
// 直调 SQLite store，否则 HTTP 打 Python（现状）。下面三个薄封装保持原签名，
// 让 runFanout / timeline 等调用点零改动。agent 读取仍走 Python HTTP（pyGetAgent）。

import { PYTHON_BACKEND_URL } from '../python-backend';

/** 读一个群（经群后端抽象）。返回蛇形 record（含 messages）或 null。 */
async function pyGet<T>(path: string): Promise<T | null> {
  // 兼容旧签名：本函数只用于群读取（path 形如 /api/groups/<id>）。提取 group_id
  // 后走后端抽象。其余路径（agent）请用 pyGetAgent。
  const m = /^\/api\/groups\/([^/]+)$/.exec(path);
  if (m) {
    const groupId = decodeURIComponent(m[1]);
    const g = await getGroupsBackend().getGroup(groupId);
    return (g as unknown as T) ?? null;
  }
  // 非群路径：HTTP 打 Python（agent 等）。
  try {
    const res = await fetch(`${PYTHON_BACKEND_URL}${path}`);
    if (!res.ok) return null;
    const json = (await res.json()) as { data?: T } | T;
    return ((json as { data?: T }).data ?? json) as T;
  } catch {
    return null;
  }
}

/**
 * 追加一条消息（经群后端抽象）。返回创建的 MessageItem（或 null）。
 * node 模式：直调 store 持久化，并把 agent/system 消息 publish 到 Node SSE 总线
 * （对齐 Python post_group_message 对 agent/system 的 publish_group_event）；user
 * 消息不 publish（前端已乐观渲染）。python 模式：HTTP 打 Python，Python 自己 publish。
 */
async function pyPostMessage(
  groupId: string,
  body: { content: string; sender_name: string; sender_kind: string; agent_id?: string },
  opts: { noDispatch?: boolean } = {},
): Promise<unknown> {
  const created = await getGroupsBackend().appendMessage(groupId, body, opts);
  if (
    process.env.SF_GROUPS_BACKEND === 'node' &&
    (body.sender_kind === 'agent' || body.sender_kind === 'system')
  ) {
    const type = body.sender_kind === 'system' ? 'system.notice' : 'agent.message';
    publishGroupEvent(groupId, { type, data: created ?? body });
  }
  return created;
}

/** Map persisted group messages → dispatcher history (user/assistant; skip system). */
function toHistory(
  messages: GroupRecord['messages'],
): ConversationMessage[] {
  const out: ConversationMessage[] = [];
  for (const m of messages ?? []) {
    const kind = m.sender_kind ?? 'user';
    if (kind === 'system') continue; // bridge notices aren't model context
    const role = kind === 'agent' ? 'assistant' : 'user';
    const text = typeof m.content === 'string' ? m.content : '';
    if (text) out.push({ role, blocks: [{ kind: 'text', text }] });
  }
  return out;
}

/**
 * Extract clean assistant text from one `text-delta` chunk value.
 *
 * spawner-bridge (CLI/ACP/MCP) forwards each SSE event verbatim as a text-delta
 * whose value is the wire line `event: <name>\ndata: <json>\n\n` — lossless on
 * the wire, but the consumer must re-parse. We pull `data.text` only from
 * `event: text` blocks (NOT `raw`/`usage`/`complete`, which also carry a
 * `text` field). ApiClientCallable (byok) yields clean text already (no
 * `event:` prefix) → passed through unchanged.
 */
function sseWireToText(value: string): string {
  if (!/^event:\s/m.test(value)) return value; // byok clean text
  let out = '';
  for (const block of value.split('\n\n')) {
    let ev = '';
    let data = '';
    for (const line of block.split('\n')) {
      if (line.startsWith('event:')) ev = line.slice(6).trim();
      else if (line.startsWith('data:')) data = line.slice(5).trim();
    }
    if (ev === 'text' && data) {
      try {
        const j = JSON.parse(data) as { text?: unknown };
        if (typeof j.text === 'string') out += j.text;
      } catch {
        /* non-JSON data line — skip */
      }
    }
  }
  return out;
}

/**
 * 2026-11-04 思考剥离（纯函数，可单测）— 从 agent 最终聊天回复里去掉
 * `<sf:thinking>…</sf:thinking>` 思考段。zhipu 思考模型（glm-4.6/5.x）经
 * ApiClientCallable 的 reasoning_content 包装，流式文本里成对/未闭合（max_tokens
 * 截断）两种形态都会出现；思考过程已由过程卡（thinking 卡）实时展示，最终
 * 消息只留正文。与 src/api/llm.ts 人设生成同款策略。
 *
 * 2026-11-05 — 补连字符形态 `<sf-thinking>`：模型模仿 sf: 协议时经常把冒号
 * 写成连字符（群聊气泡实证：`<sf-thinking>The user said…</sf-thinking>` 整段
 * 英文思考漏进中文界面）。冒号/连字符 × 成对/未闭合全部剥干净。
 */
export function stripThinking(s: string): string {
  // <sf:thinking> / <sf-thinking>（属性可选）… </sf:thinking> / </sf-thinking>。
  return s
    .replace(/<sf[:-]thinking(?:\s[^>]*)?>[\s\S]*?<\/sf[:-]thinking>/g, '')
    .replace(/<sf[:-]thinking(?:\s[^>]*)?>[\s\S]*$/g, '');
}

/**
 * G1（2026-06-13）— 网关 fanout 把 callable.turn() 吐出的 tool-use/tool-result
 * chunk 投影成 tool_call/tool_echo TimelineMessage，让会话 Timeline 真显示工具
 * 调用（前端 ToolCallChip/ToolEchoLine 渲染器+contracts 早已就位，只缺网关 emit）。
 * 映射与 timeline-projector.onToolUse/onToolResult 一致(args 截 200、空 result 跳过)。
 * gw 为 null（startGatewayRun 失败）时整体 no-op，不影响聊天主链路。
 *
 * 2026-11-06 Agent 检查器 — who 参数（可选）：群聊 fanout 每个 agent 的
 * callAgent 传入自己的 id/名，工具卡带 agent_id/agent_name 归属；单聊/老调用
 * 不传 = 无归属（additive，检查器对无归属卡不筛选）。
 */
export interface ToolOwner {
  agentId: string;
  agentName: string;
}

/** 网关 gw 接口（emitPatch 可选——老调用方/测试可能只给 emitMessage）。 */
type ToolGw = {
  nextId(): string;
  turnId: string;
  emitMessage(m: TimelineMessage): void;
  emitPatch?(p: MessagePatch): void;
} | null;

// gap #2（2026-06-24）— 按 gw 记当前未落定的 tool_call（id + 开始时间），
// 用于 tool-result 时发 tool_finalize（耗时 + 成功/失败 + 结果摘要）。WeakMap
// 随 gw 生命周期自动回收，不污染 gw 类型。
// 2026-11-06 — 单槽改 per-agent 槽（Map<agentId, open>）：并发 DAG 多 agent
// 共享同一 gw，单槽会互相顶替导致 finalize 串台/永久转圈；无 who（单聊）落
// '' 槽，行为与旧单槽完全一致。
const _openToolByGw = new WeakMap<object, Map<string, { id: string; startMs: number }>>();

/** body 看起来像错误？（与 timeline-projector.onToolResult 同启发）。 */
function looksLikeToolError(body: string): boolean {
  return /^\s*(error|exception|traceback|failed|enoent|permission denied)/i.test(body)
    || (/\b(error|failed)\b/i.test(body.slice(0, 80)) && body.length < 200);
}

export function emitToolChunk(gw: ToolGw, chunk: TurnChunk, who?: ToolOwner): void {
  if (!gw) return;
  // per-agent 开放工具槽（'' = 无归属单聊路径，与旧单槽行为一致）。
  const slotKey = who?.agentId ?? '';
  const openMap = _openToolByGw.get(gw) ?? new Map<string, { id: string; startMs: number }>();
  _openToolByGw.set(gw, openMap);
  const attribution = who ? { agent_id: who.agentId, agent_name: who.agentName } : {};
  if (chunk.type === 'tool-use') {
    let argsSummary = '';
    try {
      argsSummary =
        typeof chunk.tool.tool_input === 'string'
          ? chunk.tool.tool_input
          : JSON.stringify(chunk.tool.tool_input ?? {});
    } catch {
      argsSummary = String(chunk.tool.tool_input);
    }
    if (argsSummary.length > 200) argsSummary = argsSummary.slice(0, 200) + '…';
    // 前一个 tool 没收到 result 就被顶替 → 先落定为 ok（防永久转圈）。
    // per-agent 槽：并发 DAG 下别的 agent 的开放工具不受影响。
    const prev = openMap.get(slotKey);
    if (prev && gw.emitPatch) {
      gw.emitPatch({ id: prev.id, op: 'tool_finalize', status: 'ok', duration_ms: Math.max(0, Date.now() - prev.startMs) });
    }
    const id = gw.nextId();
    openMap.set(slotKey, { id, startMs: Date.now() });
    gw.emitMessage({
      id,
      kind: 'tool_call',
      turn_id: gw.turnId,
      ts: Date.now(),
      name: chunk.tool.tool_name,
      args_summary: argsSummary,
      status: 'running',
      ...attribution,
    });
  } else if (chunk.type === 'tool-result') {
    const body = (chunk.result.output ?? '').trim();
    // gap #2 — 落定该 agent 最近未结的 tool_call（耗时 + 成功/失败 + 结果摘要）。
    const open = openMap.get(slotKey);
    if (open && gw.emitPatch) {
      gw.emitPatch({
        id: open.id,
        op: 'tool_finalize',
        status: looksLikeToolError(body) ? 'error' : 'ok',
        duration_ms: Math.max(0, Date.now() - open.startMs),
        result_summary: summarizeToolResult(body),
      });
      openMap.delete(slotKey);
    }
    if (!body) return;
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'tool_echo',
      turn_id: gw.turnId,
      ts: Date.now(),
      body,
      ...attribution,
    });
  }
}

/**
 * Resolve the CLI/ACP/MCP working directory (cwd) for a group.
 *
 * Priority (2026-05-30):
 *   1. group.workspace_dir — user-picked absolute path (group settings DirPicker).
 *      Used verbatim if it's an existing absolute directory. The bypassed CLI
 *      can read/write here, so it's the user's explicit choice.
 *   2. Fallback scratch dir OUTSIDE the repo:
 *      `$SHADOWFLOW_CHAT_DIR | ~/.shadowflow-chat`/chat-workspaces/<groupId>.
 *      Previously this lived under the repo (`process.cwd()/.shadowflow/...`),
 *      which let `claude` follow the git root and read the whole ShadowFlow
 *      codebase — `bypassPermissions + cwd-in-repo` is the dangerous combo we
 *      avoid here (see docs/architecture/chat-cli-cwd-and-permissions.md).
 */
function resolveChatWorkspace(groupId: string, userDir?: string): string {
  if (userDir && userDir.trim() && isAbsolute(userDir.trim())) {
    const p = userDir.trim();
    try {
      if (statSync(p).isDirectory()) return p;
    } catch {
      /* user dir gone / unreadable — fall through to default scratch */
    }
  }
  const root = process.env.SHADOWFLOW_CHAT_DIR?.trim() || join(homedir(), '.shadowflow-chat');
  const dir = join(root, 'chat-workspaces', groupId.replace(/[^\w-]/g, '_'));
  try {
    mkdirSync(dir, { recursive: true });
  } catch {
    /* best-effort; spawn will surface a clearer error if it truly can't run */
  }
  return dir;
}

/** Resolve executor → callable opts (key only for byok:/anthropic-direct). */
function resolveExecutorKey(
  executor: string,
  headers: Request['headers'],
): string | undefined {
  if (executor.startsWith('byok:')) {
    const provider = executor.slice(5);
    if (isProviderId(provider)) return resolveProviderKey(provider, headers);
  }
  if (executor === 'anthropic-direct') return resolveProviderKey('anthropic', headers);
  return undefined; // cli:/acp:/mcp: don't need a key
}

/**
 * 2026-11-04 默认 executor 回退（NeverThrow：任何失败 → 'cli:claude' 现状兜底）。
 * 读取 settings/byok：第一个 enabled 且配了 key 的 provider → `byok:<id>`。
 * 让「设置页配好 zhipu key」这个动作对群聊默认对话生效，而不是让每条消息都
 * 掉进 cli:claude 静默挂起。provider 顺序读 settings 插入序（用户配的第一个
 * provider 优先），无任何可用 BYOK → 'cli:claude'（历史行为零回归）。
 */
export function pickDefaultExecutor(): string {
  try {
    // 惰性 require 与 dispatcher 同款防循环依赖。
    const { getSetting } = require('../storage/settings') as {
      getSetting: (k: string) => unknown;
    };
    const byok = getSetting('byok') as
      | { providers?: Record<string, { apiKey?: string; enabled?: boolean }> }
      | undefined;
    for (const [id, p] of Object.entries(byok?.providers ?? {})) {
      if (p?.enabled && typeof p.apiKey === 'string' && p.apiKey.trim()) {
        return `byok:${id}`;
      }
    }
  } catch {
    /* settings 不可用 → CLI 兜底 */
  }
  return 'cli:claude';
}

// ── Polynoia 对标 · 富卡片发射助手（经 gateway run 落群时间线） ───────────────

type GwLike = ReturnType<typeof startGatewayRun>;

/** intent 帧 payload（WorkBuddy 式派发决策可见化，2026-08-23）。 */
export interface IntentCardInput {
  /** 用户原始意图（原文，本函数负责截断）。 */
  intent: string;
  target_kind: 'team' | 'agent';
  target_name: string;
  reason: string;
  assignments?: IntentAssignment[];
}

/** intent 帧的意图原文截断长度（卡片只展示概览，全文在时间线里）。 */
const INTENT_TEXT_MAX = 120;

/**
 * 组装 intent 帧 payload（纯函数，可单测）：截断意图原文；拆解明细为空数组
 * 时归一为 undefined（卡片「无明细」与「无拆解」同一视觉，不伪造空列表）。
 */
export function buildIntentCard(input: IntentCardInput): {
  intent: string;
  target_kind: 'team' | 'agent';
  target_name: string;
  reason: string;
  assignments?: IntentAssignment[];
} {
  return {
    intent: input.intent.replace(/\s+/g, ' ').trim().slice(0, INTENT_TEXT_MAX),
    target_kind: input.target_kind,
    target_name: input.target_name,
    reason: input.reason,
    ...(input.assignments && input.assignments.length > 0
      ? { assignments: input.assignments }
      : {}),
  };
}

/**
 * intent 帧发射（NeverRaising）：gw 为 null / emit 抛错都静默——派发决策
 * 可视化是 additive 增强，绝不影响聊天主链路（与 startGatewayRun 失败语义一致）。
 */
export function emitIntentCard(gw: GwLike, input: IntentCardInput): void {
  if (!gw) return;
  try {
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'intent',
      turn_id: gw.turnId,
      ts: Date.now(),
      ...buildIntentCard(input),
    });
  } catch {
    /* NeverRaising */
  }
}

/** commit_record 卡 — agent 提交 / 编排者合并提交共用。 */
function emitCommitCard(gw: GwLike, c: {
  repo: string; sha: string; short_sha: string; message: string; author: string;
  date?: string; files_changed: number; insertions: number; deletions: number;
  files?: WorktreeCommit['files'];
}): void {
  if (!gw || !c.sha) return;
  gw.emitMessage({
    id: gw.nextId(),
    kind: 'commit_record',
    turn_id: gw.turnId,
    ts: Date.now(),
    repo: c.repo,
    sha: c.sha,
    short_sha: c.short_sha,
    message: c.message,
    author: c.author,
    files_changed: c.files_changed,
    insertions: c.insertions,
    deletions: c.deletions,
    ...(c.date ? { date: c.date } : {}),
    ...(c.files && c.files.length > 0 ? { files: c.files } : {}),
  });
}

/** file_diff 卡（每个变更文件一张，git-introspect 已限量截断）。 */
function emitFileDiffCards(gw: GwLike, diffs: GitFileDiff[]): void {
  if (!gw) return;
  for (const fd of diffs) {
    gw.emitMessage({
      id: gw.nextId(),
      kind: 'file_diff',
      turn_id: gw.turnId,
      ts: Date.now(),
      path: fd.path,
      added: fd.added,
      removed: fd.removed,
      lines: fd.lines,
      ...(fd.language ? { language: fd.language } : {}),
    });
  }
}

/** agent 干完即提交 + 证据卡（commit_record + file_diff）。失败静默 — 不影响聊天主链路。 */
async function commitAndEvidence(
  gw: GwLike,
  wt: PreparedWorktree,
  agentName: string,
  taskTitle: string,
): Promise<void> {
  try {
    const commit = await commitWorktree(
      wt.dir,
      `[sf] ${agentName}: ${taskTitle.slice(0, 60)}`,
      agentName,
    );
    if (!commit?.sha) return;
    emitCommitCard(gw, {
      repo: agentName,
      sha: commit.sha,
      short_sha: commit.short_sha,
      message: commit.message,
      author: commit.author,
      date: commit.date,
      files_changed: commit.files_changed,
      insertions: commit.insertions,
      deletions: commit.deletions,
      files: commit.files,
    });
    const ev = await inspectGitRun(wt.dir, wt.baseSha, undefined);
    if (ev) emitFileDiffCards(gw, ev.fileDiffs);
  } catch (e) {
    console.warn('[groups-chat] worktree commit/evidence failed (non-fatal):', e);
  }
}

/** MERGE 收尾 — 各 agent 分支并入集成分支，出合并卡/冲突表 + 冲突系统消息。 */
async function integrateAndReport(
  gw: GwLike,
  groupId: string,
  repoRoot: string,
  runKey: string,
  orderedAgents: string[],
  wtByAgent: Map<string, PreparedWorktree>,
): Promise<void> {
  if (wtByAgent.size === 0) return;
  try {
    const branches = orderedAgents
      .map((id) => wtByAgent.get(id)?.branch)
      .filter((b): b is string => !!b);
    const results = await integrateAll(repoRoot, runKey, branches);
    if (!results || results.length === 0) return;
    const rows: (string | number)[][] = [];
    for (const r of results) {
      // 分支名 agent/<agentId>/<runKey> → 反查 agent。
      const agentId = r.branch.split('/')[1] ?? r.branch;
      if (r.ok) {
        emitCommitCard(gw, {
          repo: 'integration',
          sha: r.mergeSha ?? 'unknown',
          short_sha: r.shortSha ?? '',
          message: `merge ${agentId} → ${runKey.split('-')[0]}`,
          author: 'orchestrator',
          files_changed: 0,
          insertions: r.insertions,
          deletions: r.deletions,
        });
        rows.push([agentId, '已合并', r.insertions, r.deletions]);
      } else {
        rows.push([agentId, '冲突 needs-manual', r.conflicts.length, r.conflicts.slice(0, 3).join('、')]);
        await pyPostMessage(groupId, {
          content: `[worktree] ${agentId} 的分支合并冲突（needs-manual）：${r.conflicts.join('、') || '未知文件'}`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
      }
    }
    if (gw && rows.length > 1) {
      gw.emitMessage({
        id: gw.nextId(),
        kind: 'table_panel',
        turn_id: gw.turnId,
        ts: Date.now(),
        caption: '回合合并结果',
        columns: ['Agent', '结果', '新增', '删除 / 冲突文件'],
        rows,
      });
    }
  } catch (e) {
    console.warn('[groups-chat] worktree integration failed (non-fatal):', e);
  }
}

/**
 * Background fan-out: generate + persist one reply per group agent.
 * Never throws to the caller (errors become sender_kind='system' notices).
 * @param latestUserText 最新用户消息原文（mention 解析用；调用方从持久化记录
 *   取，缺省时 runFanout 自行从 group.messages 反查——测试/旧调用方兼容）。
 */
async function runFanout(
  groupId: string,
  executor: string,
  model: string | undefined,
  headers: Request['headers'],
  latestUserText?: string,
): Promise<void> {
  const apiKey = resolveExecutorKey(executor, headers);

  const group = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
  if (!group) return;
  // CLI/ACP/MCP need a cwd; byok/anthropic-direct ignore it. Honor the group's
  // user-picked workspace_dir, else a repo-external scratch dir.
  const workspace = resolveChatWorkspace(groupId, group.workspace_dir);
  const allAgentIds = (group.agent_ids ?? []).slice(0, MAX_FANOUT_AGENTS);
  if (allAgentIds.length === 0) {
    await pyPostMessage(groupId, {
      content: '[chat] No agents are members of this group.',
      sender_name: 'system',
      sender_kind: 'system',
    }).catch(() => {});
    return;
  }

  // ── @ 提及定向派活（OpenBot 语义）────────────────────────────────────────
  // 提取消息中的 @token 并对照成员名单解析；命中 ≥1 个成员 → 只派活给被点名者。
  const userText =
    typeof latestUserText === 'string' && latestUserText.trim()
      ? latestUserText
      : ([...(group.messages ?? [])]
          .reverse()
          .find((m) => (m.sender_kind ?? 'user') === 'user')?.content ?? '');
  const rosterCandidates: MentionCandidate[] = [];
  for (const id of allAgentIds) {
    try {
      const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(id)}`);
      rosterCandidates.push({ id, name: a?.name || id });
    } catch {
      rosterCandidates.push({ id, name: id });
    }
  }
  const { mentionedIds, cleanText } = parseMentions(userText, rosterCandidates);
  const mentioned = new Set(mentionedIds);
  const agentIds = mentioned.size > 0 ? allAgentIds.filter((id) => mentioned.has(id)) : allAgentIds;

  // @ 未命中可见提示（零 LLM）：消息里有 @token 但一个都没对上成员 → 用户
  // 以为在点名、系统却全员派发，这是演示里最容易被问「为什么 @ 没生效」的
  // 场景。落一条 system 提示（可解释性 > 沉默降级）。纯文本无 @ → 不打扰。
  const hasAtToken = /(^|[\s，。！？、：；）】」』》〉【「『,.!?;:)\]])@[^\s]/u.test(userText);
  if (!mentioned.size && hasAtToken) {
    const names = rosterCandidates.map((c) => `@${c.name}`).join('、');
    await pyPostMessage(groupId, {
      content: `[mention] 消息里的 @ 没有匹配到任何群成员，已按常规流程派发给全体成员。可点名的成员：${names}`,
      sender_name: 'system',
      sender_kind: 'system',
    }).catch(() => {});
  }

  // B3 · 网关过程事件 — 本轮 fan-out 开一条 gateway run（互链 conversation 下），
  // 执行期过程经 run 管线 emit；B2 GET /:id/timeline 自动归并回放。
  // startGatewayRun 失败返回 null（聊天主链路照常），所有 gw 操作 `gw?.` 防御。
  const gw = startGatewayRun(groupId, userText);

  try {
    // 2026-06-03 Phase 2a — group 绑了 team 且能读到单一真源 DAG → 按拓扑调度多 agent。
    // 读不到 team(无 team_id / 文件缺失 / 无成员)→ 落到下面的串行 fan-out 降级。
    // ⚠ Phase 2b 剩余(本轮已落:并发上限/外部取消/节点超时/重试):B2 中断恢复(run 状态落盘+重启续跑)、
    //   B3 完整插话续跑(本轮只做"新消息→取消上一轮"最小语义)仍待后续。
    if (shouldRunTeamDag(group)) {
      const { team } = loadTeamForRun(group.team_id!);
      if (team && team.members.length > 0) {
        // ── @ 提及定向派活（OpenBot 语义）─────────────────────────────────
        // 有命中提及 → 团队收缩为被提及节点的诱导子图（成员/边双裁剪，conditional
        // 返工边保留），且跳过 LLM 意图拆解（点名即完整任务说明，无需再拆）。
        const fullRoster = team;
        const team2 =
          mentioned.size > 0 ? restrictTeamToMentions(fullRoster, [...mentioned]) : fullRoster;
        const mentionRouted = mentioned.size > 0 && team2.members.length > 0;
        const effTeam = mentionRouted ? team2 : fullRoster;
        if (!mentionRouted) {
          // 提及了成员但一个都不在 team 名单里（如 @ 的是非团队成员）→ 当没提过。
          mentioned.clear();
        }

        // group 已在 runFanout 顶部加载(含 messages);DAG 用单次快照即可(上游上下文经 upstream 参数流转,不靠 history)。
        const history0 = toHistory(group.messages);
        const latestUser0 = [...history0].reverse().find((m) => m.role === 'user');
        // 提及路由时用清洗文本（去掉 @token）当派发 prompt，Agent 不被 @噪音干扰。
        const userPrompt =
          (mentionRouted ? cleanText : '')
            || latestUser0?.blocks.map((b) => (b.kind === 'text' ? b.text : '')).join('')
            || '';

        // ── Polynoia INTENT_PARSE（2026-08-15）─────────────────────────────
        // 编排者前置拆解：BYOK 有 key 时用 LLM 把用户消息拆成 per-agent 子任务
        // prompt（生成合适 prompt 分阶段派发）；任何失败 → null → 降级为原文
        // 分发（现状行为，零回归）。@ 提及定向派活时跳过（点名即任务说明）。
        const rosterEntries = await Promise.all(
          effTeam.members.map(async (id) => {
            const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(id)}`).catch(() => null);
            return a ? { id, name: a.name || id, soul: a.soul ?? '' } : null;
          }),
        );
        const roster = rosterEntries.filter((r): r is { id: string; name: string; soul: string } => r !== null);
        const rosterName = (id: string): string => roster.find((r) => r.id === id)?.name ?? id;

        const parseProvider = executor.startsWith('byok:')
          ? executor.slice(5)
          : executor === 'anthropic-direct'
            ? 'anthropic'
            : null;
        let parsedTasks: ParsedTask[] | null = null;
        if (
          !mentionRouted &&
          parseProvider && apiKey && isProviderId(parseProvider) && userPrompt.trim()
        ) {
          parsedTasks = await decomposeWithLlm({
            userText: userPrompt,
            agents: roster,
            provider: parseProvider,
            apiKey,
            model,
          });
        }
        const taskByAgent = new Map<string, ParsedTask>();
        if (parsedTasks) for (const t of parsedTasks) taskByAgent.set(t.agentId, t);

        // ── DISPATCH 决策可见化：intent 帧（NeverRaising）───────────────────
        // 用户说一句话后能立刻看到「派给了谁、为什么」：拆解成功 → 团队 +
        // per-agent 明细；拆解不可用（无 key/失败）→ 团队 + 降级原因。卡片本体
        // 由前端 NeoGroupChat 的 NeoDispatchCard 渲染。
        emitIntentCard(gw, {
          intent: userPrompt,
          target_kind: 'team',
          target_name: team.name ?? group.team_id!,
          reason: mentionRouted
            ? `用户点名 @${mentionedIds
                .map((id) => rosterName(id))
                .join('、')}，定向派发（跳过意图拆解）`
            : parsedTasks
              ? `编排者拆解为 ${parsedTasks.length} 个子任务，按 DAG 分层派发`
              : '拆解不可用（无 BYOK key 或解析失败），用户原文分发给全体成员',
          assignments: mentionRouted
            ? effTeam.members.map((id) => ({
                agent_id: id,
                name: rosterName(id),
                title: '定向派活',
              }))
            : parsedTasks?.map((t) => ({
                agent_id: t.agentId,
                name: rosterName(t.agentId),
                title: t.title,
              })),
        });

        // ── DISPATCH 可视化：plan_card（层号 = 并行批次）───────────────────
        const { layers } = computeDagLayers(effTeam.members, effTeam.edges);
        let planCardId: string | null = null;
        if (gw && team.members.length >= 2) {
          const planTasks: PlanTaskRow[] = [];
          layers.forEach((layer, li) => {
            for (const id of layer) {
              planTasks.push({
                id: `node:${id}`,
                title: taskByAgent.get(id)?.title ?? rosterName(id),
                assignee: rosterName(id),
                status: 'pending',
                batch: li + 1,
              });
            }
          });
          if (planTasks.length >= 2) {
            planCardId = gw.nextId();
            gw.emitMessage({
              id: planCardId,
              kind: 'plan_card',
              turn_id: gw.turnId,
              ts: Date.now(),
              title: '编排计划',
              ...(userPrompt ? { goal: userPrompt } : {}),
              tasks: planTasks,
            });
          }
        }
        const planTaskUpdate = (agentId: string, patch: Partial<PlanTaskRow>): void => {
          if (gw && planCardId) {
            gw.emitPatch({ id: planCardId, op: 'plan_update_task', task_id: `node:${agentId}`, patch });
          }
        };

        // ── Polynoia worktree 隔离 ─────────────────────────────────────────
        // 仅当群 workspace 是 git 仓库时启用（每 agent 一分支一 worktree，回合
        // 起始重置）；scratch 共享目录 / 非 git → 行为与现状一致。
        const runKey = `${groupId}-${Date.now()}`;
        const wtByAgent = new Map<string, PreparedWorktree>();
        if (await isGitWorkable(workspace)) {
          for (const id of effTeam.members) {
            const wt = await prepareWorktree(workspace, runKey, id).catch(() => null);
            if (wt) wtByAgent.set(id, wt);
          }
        }

        // ── 交接记录（2026-11-05，OpenBot hop 模型）───────────────────────
        // 本回合一个 turn_seq；SQLite 落库失败时降级为内存 Map（聊天主链路零影响）。
        let turnSeq = 0;
        let hopStore: HopRecorder | null = null;
        // 2026-11-05 Task#10 — hop 生命周期实时播报（hop_card 帧 + hop_update patch）：
        // SQLite 侧照旧落库，播报属 best-effort（gw 为 null / emit 抛错都不影响主链路）。
        // roster 名解析：hopIdFor 只拿 agentId，这里维护 id→name 快照表。
        const agentNameById = new Map<string, string>();
        const hopCardIdByEdge = new Map<string, string>(); // "from→to" → hop_card 帧id
        const hopOpenedAtByEdge = new Map<string, number>();
        const resolveAgentName = async (agentId: string): Promise<string> => {
          const hit = agentNameById.get(agentId);
          if (hit) return hit;
          const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`).catch(() => null);
          const name = a?.name || agentId;
          agentNameById.set(agentId, name);
          return name;
        };
        /** 把 SQLite hopStore 的三次回调包上播报；emit 失败静默（best-effort）。 */
        const emitHopFrame = (fn: () => void): void => {
          try {
            fn();
          } catch { /* best-effort */ }
        };
        try {
          turnSeq = nextTurnSeq(groupId);
          const dbStore: HopRecorder = {
            open: (edge) => openHop({ group_id: groupId, turn_seq: turnSeq, from_agent: edge.from, to_agent: edge.to }),
            start: (id) => { try { startHop(id); } catch { /* best-effort */ } },
            settle: (id, status, opts) => { try { settleHop(id, status, opts); } catch { /* best-effort */ } },
          };
          if (gw) {
            hopStore = {
              open: (edge) => {
                const hopId = dbStore.open(edge);
                // 播报帧异步准备（open 回调本身要求同步返回 hopId，不能 await）。
                void (async () => {
                  const [fromName, toName] = await Promise.all([resolveAgentName(edge.from), resolveAgentName(edge.to)]);
                  const cardId = gw.nextId();
                  const key = `${edge.from}→${edge.to}`;
                  hopCardIdByEdge.set(key, cardId);
                  hopOpenedAtByEdge.set(key, Date.now());
                  emitHopFrame(() =>
                    gw.emitMessage({
                      id: cardId,
                      kind: 'hop_card',
                      turn_id: gw.turnId,
                      ts: Date.now(),
                      from_agent: edge.from,
                      to_agent: edge.to,
                      from_name: fromName,
                      to_name: toName,
                      status: 'pending',
                    }),
                  );
                })();
                return hopId;
              },
              start: (id) => {
                dbStore.start(id);
                // start 回调只拿 hopId（不拿边），由 SQLite 行反查边 key —— 但为避免
                // 逐帧查库，这里用「settled 未知的帧保持 pending」策略：播报粒度到
                // settle 已足够（pending → 终态），start 不单独 patch。
              },
              settle: (id, status, opts) => {
                dbStore.settle(id, status, opts);
                // settle 同样只拿 hopId —— 边 key 反查走 SQLite 行（listHopsByTurn 本回合），
                // 但 settle 高频小查询代价可忽略；找不到对应帧则静默（降级安全）。
                void (async () => {
                  try {
                    const hops = listHopsByTurn(groupId, turnSeq);
                    const hop = hops.find((h) => h.id === id);
                    if (!hop) return;
                    const key = `${hop.from_agent}→${hop.to_agent}`;
                    const cardId = hopCardIdByEdge.get(key);
                    if (!cardId) return;
                    const openedAt = hopOpenedAtByEdge.get(key) ?? Date.now();
                    emitHopFrame(() =>
                      gw.emitPatch({
                        id: cardId,
                        op: 'hop_update',
                        patch: {
                          status,
                          ...(opts?.outputChars !== undefined ? { output_chars: opts.outputChars } : {}),
                          ...(opts?.detail ? { detail: opts.detail } : {}),
                          duration_ms: Date.now() - openedAt,
                        },
                      }),
                    );
                  } catch { /* best-effort */ }
                })();
              },
            };
          } else {
            hopStore = dbStore;
          }
        } catch { hopStore = null; }

        // 记忆交接沉淀（2026-11-05）— 本轮实际发言 agent 收集器（执行序），
        // 回合结束后 sinkRoundHandoff 落交接包（零 LLM、autoLearn 开关）。
        const roundSpeakers: Array<{ id: string; name: string; excerpt: string }> = [];

        const deps: RunTeamDagDeps = {
          getAgent: async (agentId) => {
            const a = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`);
            return a ? { name: a.name || agentId, soul: a.soul ?? '' } : null;
          },
          callAgent: async ({ agentId, name, soul, upstream, signal }) => {
            // 用 agentId/name/soul/upstream/signal:agent 回复由 runTeamDagFanout 经独立 postMessage
            // 落库（聊天消息路径零变化）;name 仅用于 B3 过程卡 label。
            // signal 来自 runNodeWithPolicy 的 per-attempt 控制器(超时/外部取消即 fire)→ 取消在飞 turn。
            const upstreamText = upstream.length
              ? `\n\n=== 上游 agent 产出 ===\n${upstream.map((u) => `[${u.from}]\n${u.text}`).join('\n\n')}`
              : '';
            // INTENT_PARSE 产物优先 — 编排者拆出的 per-agent 子任务 prompt；
            // 无拆解（无 key/失败/未分配）→ 用户原文（现状）。
            const task = taskByAgent.get(agentId);
            const basePrompt = task ? task.prompt : userPrompt;
            // worktree 隔离 — 本轮该 agent 的专属工作目录。
            const wt = wtByAgent.get(agentId);
            // plan_card 任务行 → running。
            planTaskUpdate(agentId, { status: 'running' });
            // B3 — DAG 节点粒度过程卡（重试时每个 attempt 一张新卡，可见即真实）。
            const thinkingId = gw?.nextId();
            const startedAt = Date.now();
            if (gw && thinkingId) {
              gw.emitMessage({
                id: thinkingId,
                kind: 'thinking',
                turn_id: gw.turnId,
                ts: startedAt,
                label: `${name} 正在思考`,
                status: 'streaming',
                agent_id: agentId,
                agent_name: name,
              });
            }
            let buf = '';
            let errMsg = '';
            try {
              const callable = resolveCallable(executor, { apiKey, model, workspace: wt?.dir ?? workspace });
              for await (const chunk of callable.turn({
                system: soul,
                prompt: basePrompt + upstreamText,
                history: history0.slice(0, -1),
                signal,
                model,
              })) {
                if (chunk.type === 'text-delta') {
                  const piece = sseWireToText(chunk.value);
                  buf += piece;
                  // B3 — 流式片段就地点亮（现有解析粒度 = event:text 的干净文本）。
                  if (gw && thinkingId && piece) {
                    gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: piece });
                  }
                } else if (chunk.type === 'thinking-delta') {
                  // 2026-11-04 — API 路结构化思考通道：只点亮过程卡，不进 buf。
                  if (gw && thinkingId && chunk.value) {
                    gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: chunk.value });
                  }
                } else if (chunk.type === 'tool-use' || chunk.type === 'tool-result') {
                  // G1 — 工具调用/结果就地点亮（tool_call/tool_echo 卡）；
                  // 2026-11-06 检查器 — 带 agent 归属（按 agent 筛后台活动）。
                  emitToolChunk(gw, chunk, { agentId: agentId, agentName: name });
                } else if (chunk.type === 'error') {
                  errMsg = chunk.error?.message ?? 'stream error';
                  break;
                }
              }
            } catch (e) {
              errMsg = e instanceof Error ? e.message : String(e);
            }
            if (gw && thinkingId) {
              const elapsed = Date.now() - startedAt;
              gw.emitPatch({ id: thinkingId, op: 'thinking_finalize', duration_ms: elapsed });
              if (errMsg) {
                gw.emitMessage({
                  id: gw.nextId(),
                  kind: 'raw',
                  turn_id: gw.turnId,
                  ts: Date.now(),
                  body: `[chat] ${name} 出错：${errMsg}`,
                  source: 'chat-gateway',
                });
              }
              gw.emitMessage({
                id: gw.nextId(),
                kind: 'msg_foot',
                turn_id: gw.turnId,
                ts: Date.now(),
                status: 'done',
                elapsed_ms: elapsed,
              });
            }
            // plan_card 任务行落终态。
            planTaskUpdate(agentId, errMsg
              ? { status: 'failed' }
              : { status: 'done', elapsed_ms: Date.now() - startedAt });
            // Polynoia MERGE 前半 — 干完即提交 worktree 产物 + 证据卡
            // （commit_record / file_diff）；无 worktree 或干净树 → 静默跳过。
            if (!errMsg && wt) {
              await commitAndEvidence(gw, wt, name, task?.title ?? userPrompt);
            }
            // 2026-11-04 思考剥离 — 与串行路径同款：<sf:thinking> 段不进最终回复。
            return { text: stripThinking(buf), error: errMsg || undefined };
          },
          postMessage: async (m) => {
            await pyPostMessage(groupId, {
              content: m.content,
              sender_name: m.sender_name,
              sender_kind: m.sender_kind,
              // U0 绑角色 — 透传 agent 回话的发送者 agent_id（system 消息无）。
              ...(m.agent_id ? { agent_id: m.agent_id } : {}),
            }).catch(() => {});
            // 记忆交接沉淀（2026-11-05）— 收集本轮实际发言的 agent（执行序）。
            if (m.sender_kind === 'agent' && m.agent_id) {
              roundSpeakers.push({
                id: m.agent_id,
                name: m.sender_name,
                excerpt: m.content.replace(/\s+/g, ' ').trim().slice(0, 160),
              });
            }
          },
          // 交接记录（2026-11-05）— hopStore 为 null（SQLite 异常）时省略，执行器走无记录路径。
          ...(hopStore ? { hops: hopStore } : {}),
          // ── approve 边人工审批门（2026-11-05，OpenBot 审批纪律）────────────
          // 执行器遇带 approve 入边的节点 → 挂起 pendingApprovals 等用户决定；
          // 批准放行 / 拒绝标 blocked。无 approve 边的团队零开销。
          ...(effTeam.edges.some((e) => e.kind === 'approve')
            ? {
                approval: {
                  request: ({ nodeId, nodeName }: { nodeId: string; nodeName: string; preview: string; signal: AbortSignal }) =>
                    new Promise<'approved' | 'rejected'>((resolve) => {
                      const key = `${groupId}:${nodeId}`;
                      pendingApprovals.set(key, resolve);
                      // 外部取消（用户插话换轮/停止生成）→ 视作拒绝收场，不悬挂。
                      // signal 由执行器传入（runTeamDagFanout 的 opts.signal）。
                      // 这里借 postMessage 之外的通道不好拿 signal —— 挂 30 分钟
                      // 兜底超时（与 run 超时同量级，避免永久 pending 占内存）。
                      setTimeout(() => {
                        if (pendingApprovals.delete(key)) {
                          try { resolve('rejected'); } catch { /* settled */ }
                        }
                      }, 30 * 60_000).unref?.();
                    }).then((v) => {
                      // 决定落一条系统消息（审批留痕；postMessage 失败不回传）。
                      void pyPostMessage(groupId, {
                        content: `[approval] ${nodeName} 的审批结果：${v === 'approved' ? '已批准 ✅' : '已拒绝 ❌'}`,
                        sender_name: 'system',
                        sender_kind: 'system',
                      }).catch(() => {});
                      return v;
                    }),
                },
                onNodeBlocked: (blockedId: string) => {
                  // plan_card 任务行 → blocked（OpenBot work_items 语义：审批拒 = 不再等）。
                  planTaskUpdate(blockedId, { status: 'blocked' });
                },
              }
            : {}),
        };
        let dagController: AbortController | undefined;
        try {
          dagController = swapDagRun(groupId, activeDagRuns);
          await runTeamDagFanout(effTeam, deps, userPrompt, {
            signal: dagController.signal,
            maxConcurrency: MAX_FANOUT_AGENTS,
            // nodeTimeoutMs/defaultMaxRetries 用 runTeamDagFanout 默认值(120s / 1)。
          });
        } finally {
          // 仅当注册表里仍是本 controller 时才删(避免误删后来者)。
          if (dagController && activeDagRuns.get(groupId) === dagController) activeDagRuns.delete(groupId);
        }
        // 交接摘要（零 LLM，从 hops 表现算）— 对齐「记忆交接」体验：本回合谁把
        // 什么交给了谁、哪里断了他能接住。postMessage 失败静默（best-effort）。
        if (hopStore) {
          try {
            const summary = summarizeHops(groupId, turnSeq);
            if (summary) {
              await pyPostMessage(groupId, {
                content: summary,
                sender_name: 'system',
                sender_kind: 'system',
              });
            }
          } catch { /* best-effort */ }
        }
        // 记忆交接沉淀（2026-11-05 GrokBot 对齐）— 回合结论落 memory_handoffs
        // 交接包（最后发言 → 首位执行者），下游 agent accept 后能接班。静默。
        sinkRoundHandoff({ groupId, turnSeq, goal: userPrompt, speakers: roundSpeakers });
        // ── Polynoia AGGREGATE/MERGE 收尾 ─────────────────────────────────
        // 各 agent 分支按 DAG 层序并入集成分支 sf/run/<runKey>（专用 integration
        // worktree，不碰用户检出分支）；合并卡 / 冲突表 + 冲突系统消息。
        // 用户插话取消的回合不合并（半成品分支留给 needs-manual）。
        if (!dagController?.signal.aborted) {
          await integrateAndReport(
            gw,
            groupId,
            workspace,
            runKey,
            layers.flat(),
            wtByAgent,
          );
        }
        // 用户插话取消上一轮 → 'canceled'；否则本轮过程完整 → 'succeeded'。
        gw?.finish(dagController?.signal.aborted ? 'canceled' : 'succeeded');
        return;
      }
    }

    // ── 串行降级路径的 worktree 隔离（无 team_id 时）──────────────────────
    // 每 agent 一个 worktree（git 仓库 workspace 时）；无 plan_card（单人无拆解）。
    const serialRunKey = `${groupId}-serial-${Date.now()}`;
    const serialWt = new Map<string, PreparedWorktree>();
    // 记忆交接沉淀收集器（2026-11-05）— 串行路径实际发言 agent（执行序）。
    const serialSpeakers: Array<{ id: string; name: string; excerpt: string }> = [];
    // 本轮派发 prompt（@ 清洗文本或用户原文最后一条；沉淀 summary 用）。
    let serialPrompt = '';
    if (await isGitWorkable(workspace)) {
      for (const id of agentIds) {
        const wt = await prepareWorktree(workspace, serialRunKey, id).catch(() => null);
        if (wt) serialWt.set(id, wt);
      }
    }

    for (const agentId of agentIds) {
      // Reload each round so later agents see earlier replies (fan-out semantics).
      const fresh = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
      const history = toHistory(fresh?.messages);
      const latestUser = [...history].reverse().find((m) => m.role === 'user');
      // @ 提及路由时用清洗文本（@token 已删）当 prompt，Agent 不吃 @ 噪音。
      const prompt =
        (mentioned.size > 0 ? cleanText : '')
          || latestUser?.blocks.map((b) => (b.kind === 'text' ? b.text : '')).join('')
          || '';
      if (prompt) serialPrompt = prompt;

      const agent = await pyGet<AgentRecord>(`/api/agents/${encodeURIComponent(agentId)}`);
      if (!agent) {
        await pyPostMessage(groupId, {
          content: `[chat] Agent '${agentId}' not found.`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      const agentName = agent.name || agentId;
      const soul = agent.soul ?? '';

      // intent 帧（NeverRaising）— 串行降级路径的派发决策：未绑团队 → 按成员
      // 逐个派发。仅多成员群展示派发卡（对群聊有「谁在处理」信息量）；
      // DM/单员工群 1:1 对话无派发语义，跳过（2026-10-31 用户反馈：单聊页
      // 不应出现「群未绑定团队」群聊文案）。
      if (group.kind !== 'dm' && agentIds.length > 1) {
        emitIntentCard(gw, {
          intent: prompt,
          target_kind: 'agent',
          target_name: agentName,
          reason: mentioned.size > 0
            ? '用户点名，定向派发（群未绑定团队）'
            : '群未绑定团队，按成员依次处理用户原文',
        });
      }

      // B3 — 串行路径过程卡：thinking 占位 → 流式 append → finalize + msg_foot。
      const thinkingId = gw?.nextId();
      const startedAt = Date.now();
      if (gw && thinkingId) {
        gw.emitMessage({
          id: thinkingId,
          kind: 'thinking',
          turn_id: gw.turnId,
          ts: startedAt,
          label: `${agentName} 正在思考`,
          status: 'streaming',
          agent_id: agentId,
          agent_name: agentName,
        });
      }

      // 2026-11-04「停止生成」— 串行路径同样登记进 activeDagRuns（swap 语义
      // 顺带 abort 上一轮残留），使 POST /:id/stop 能真中断 for-await 流。
      const ctrl = swapDagRun(groupId, activeDagRuns);
      let buf = '';
      let errMsg = '';
      // worktree 隔离 — 该 agent 专属目录（git 仓库 workspace 时）。
      const wt = serialWt.get(agentId);
      try {
        const callable = resolveCallable(executor, { apiKey, model, workspace: wt?.dir ?? workspace });
        for await (const chunk of callable.turn({
          system: soul,
          prompt,
          history: history.slice(0, -1), // exclude the just-read latest user (it's the prompt)
          signal: ctrl.signal,
          model,
        })) {
          if (chunk.type === 'text-delta') {
            const piece = sseWireToText(chunk.value);
            buf += piece;
            // B3 — 流式片段就地点亮（现有解析粒度 = event:text 的干净文本）。
            if (gw && thinkingId && piece) {
              gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: piece });
            }
          } else if (chunk.type === 'thinking-delta') {
            // 2026-11-04 — API 路结构化思考通道（ApiClientCallable reasoning_content
            // → thinking-delta）：就近点亮过程卡，绝不混进最终回复 buf。
            if (gw && thinkingId && chunk.value) {
              gw.emitPatch({ id: thinkingId, op: 'thinking_append_body', chunk: chunk.value });
            }
          } else if (chunk.type === 'tool-use' || chunk.type === 'tool-result') {
            // G1 — 工具调用/结果就地点亮（tool_call/tool_echo 卡）；
            // 2026-11-06 检查器 — 带 agent 归属（串行路径同样可按 agent 筛）。
            emitToolChunk(gw, chunk, { agentId: agentId, agentName: agentName });
          } else if (chunk.type === 'error') {
            errMsg = chunk.error?.message ?? 'stream error';
            break;
          }
        }
      } catch (e) {
        errMsg = e instanceof Error ? e.message : String(e);
      }
      // B3 — 无论成败（含 2026-11-06 修复：abort 中断）都先收口本 agent 的
      // 过程卡。此前 abort 时直接 break 跳过收口，thinking 卡永远停在
      // streaming（刷新后回放依旧转圈）。中断 = 静默收口：finalize +
      // msg_foot done，但不发错误 raw 卡、不发聊天消息（与停止语义一致）。
      if (gw && thinkingId) {
        const elapsed = Date.now() - startedAt;
        gw.emitPatch({ id: thinkingId, op: 'thinking_finalize', duration_ms: elapsed });
        if (errMsg && !ctrl.signal.aborted) {
          gw.emitMessage({
            id: gw.nextId(),
            kind: 'raw',
            turn_id: gw.turnId,
            ts: Date.now(),
            body: `[chat] ${agentName} 出错：${errMsg}`,
            source: 'chat-gateway',
          });
        }
        gw.emitMessage({
          id: gw.nextId(),
          kind: 'msg_foot',
          turn_id: gw.turnId,
          ts: Date.now(),
          status: 'done',
          elapsed_ms: elapsed,
        });
      }

      // 2026-11-04「停止生成」— 用户经 POST /:id/stop 中断本 agent 的流：
      // 折叠成静默取消（上面已收口过程卡；不记「出错」raw 卡、不发系统
      // 消息），直接跳出 for 循环结束本轮 fan-out；gateway run 已由 stop
      // 路由经 cancelRunSession 终结。
      if (ctrl.signal.aborted) break;

      if (errMsg) {
        await pyPostMessage(groupId, {
          content: `[chat] ${agentName} 出错：${errMsg}`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      // 2026-11-04 思考剥离 — 最终聊天回复不含 <sf:thinking> 思考段
      // （思考已在过程卡实时流式展示）；全剥空 → 当空回复收口。
      const reply = stripThinking(buf).trim();
      if (!reply) {
        await pyPostMessage(groupId, {
          content: `[chat] ${agentName} 返回空回复。`,
          sender_name: 'system',
          sender_kind: 'system',
        }).catch(() => {});
        continue;
      }
      // agent 最终回复仍走 pyPostMessage（聊天消息路径零变化）。
      // 2026-10-31 — 补 agent_id 透传（DAG 路径 U0 同款）：前端 agentById
      // 按 agent_id 命中 DiceBear 头像，缺省 → 字母色块兜底（头像「不绑定」根因）。
      await pyPostMessage(groupId, {
        content: reply,
        sender_name: agentName,
        sender_kind: 'agent',
        agent_id: agentId,
      }).catch(() => {});
      // 记忆交接沉淀收集器 — 串行路径同款（执行序）。
      serialSpeakers.push({
        id: agentId,
        name: agentName,
        excerpt: reply.replace(/\s+/g, ' ').trim().slice(0, 160),
      });
      // 串行路径同样「干完即提交」— worktree 产物 + 证据卡。
      if (wt) {
        await commitAndEvidence(gw, wt, agentName, prompt);
      }
    }
    // 仅当注册表里仍是本轮 controller 时才删（避免误删后来者；DAG 路径 finally 同款）。
    const serialCtrl = activeDagRuns.get(groupId);
    if (serialCtrl && !serialCtrl.signal.aborted) activeDagRuns.delete(groupId);
    // 串行路径收尾：各 agent 分支按执行序并入集成分支。
    await integrateAndReport(gw, groupId, workspace, serialRunKey, agentIds, serialWt);
    // 记忆交接沉淀（2026-11-05 GrokBot 对齐）— 多 agent 串行回合同样落交接包。
    // turn_seq 用负数时间戳锚（串行路径无 hop turnSeq；shift_id 幂等锚粒度到轮）。
    sinkRoundHandoff({
      groupId,
      turnSeq: -Date.now(),
      goal: serialPrompt,
      speakers: serialSpeakers,
    });
    gw?.finish('succeeded');
  } catch (e) {
    // 未捕获异常：过程流以 raw 卡可见地收口，run 标 failed；异常继续上抛
    // （调用方 fire-and-forget 的 .catch 负责 console.warn，行为不变）。
    if (gw) {
      const msg = e instanceof Error ? e.message : String(e);
      gw.emitMessage({
        id: gw.nextId(),
        kind: 'raw',
        turn_id: gw.turnId,
        ts: Date.now(),
        body: `[chat-gateway] fan-out 异常：${msg}`,
        source: 'chat-gateway',
      });
      gw.finish('failed');
    }
    throw e;
  }
}

// ── B2 · GET /api/groups/:id/timeline ────────────────────────────────────────
// 统一消息读路径 (unified-conversation-core-plan-2026-06-11 §B2)：把一个群的
// 完整会话历史聚合成前端 Timeline 渲染器可直接消费的 TimelineMessage[]：
//   a) 聊天消息（Python 群记录 MessageItem）→ chatMessagesToTimeline 适配
//      （user→user_turn / agent→assistant_text / system→raw，turn_id 按 user
//      消息切段）；
//   b) B1 互链 conversation 下每个 run session 的事件日志（run-event-bus 内存
//      + run-event-store 落盘，经 getRunReplay 统一取出）→ replayTimeline
//      重放 message/message-patch 得到最终 TimelineMessage[]；
//   c) 两路按 ts 升序归并；先全量不分页，上限 500 条（保最新）+ truncated 标记。
// 响应: { group_id, messages: TimelineMessage[], runs: [{session_id,status}], truncated }

/** 全量上限：超过只保留最新的 500 条（truncated: true）。 */
const TIMELINE_MAX_MESSAGES = 500;

// ── POST /api/groups/:id/stop ────────────────────────────────────────────────
// 2026-11-04「停止生成」（用户反馈：点暂停按钮对话停不下来，不合理）—
// 主动取消该群当前 fan-out 轮：abort fan-out AbortController（DAG 停止调度
// 后续节点 / 串行 for-await 断流）+ cancelRunSession 终结互链 conversation 下
// 所有 running gateway run（timeline runs 立即翻终态 → 前端 busy 解除）。
// 幂等：无在跑轮 → stopped=false，前端照样本地退出 busy。
router.post('/:id/stop', (req: Request, res: Response) => {
  const groupId = req.params.id;
  const stopped = stopGroupFanout(groupId);
  res.json({ group_id: groupId, stopped });
});

/**
 * GET /api/groups/:id/hops — agent 间交接记录查询（2026-11-05，OpenBot hop 模型）。
 * ?turns=N 取最近 N 个回合（默认 1，上限 20）；?all=1 展开为逐条 hop 数组。
 * 默认返回紧凑摘要文本（与回合结束 postMessage 同源，前端可直接渲染）。
 */
router.get('/:id/hops', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const turns = Math.min(Math.max(Number(req.query.turns ?? 1) || 1, 1), 20);
    const hops = listRecentHops(groupId, turns);
    const turnSeqs = [...new Set(hops.map((h) => h.turn_seq))];
    if (req.query.all === '1') {
      res.json({ group_id: groupId, turns: turnSeqs.sort((a, b) => b - a), hops });
      return;
    }
    const summaries = turnSeqs
      .sort((a, b) => b - a)
      .map((t) => ({ turn_seq: t, summary: summarizeHops(groupId, t) }))
      .filter((s) => s.summary);
    res.json({ group_id: groupId, turns: turnSeqs.sort((a, b) => b - a), summaries });
  })().catch((e) => {
    const msg = e instanceof Error ? e.message : String(e);
    if (!res.headersSent) {
      res.status(500).json({ error: { code: 'HOPS_FAILED', message: msg } });
    }
  });
});

router.get('/:id/timeline', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const group = await pyGet<GroupRecord>(`/api/groups/${encodeURIComponent(groupId)}`);
    if (!group) {
      // pyGet 把「Python 没起」和「群不存在」都折叠成 null；对读路径两者的
      // 用户语义一致（拿不到这个群）——用 404 + 提示语区分排查方向。
      res.status(404).json({
        error: {
          code: 'GROUP_NOT_FOUND',
          message: `group ${groupId} not found (or Python backend unreachable)`,
        },
      });
      return;
    }

    // a) 聊天消息适配。
    const chatMessages = chatMessagesToTimeline(group.messages ?? []);

    // b) 互链 run 的过程消息归并。无互链 conversation = 纯聊天群，runs 为空。
    const runs: Array<{ session_id: string; status: string }> = [];
    const runMessages: TimelineMessage[] = [];
    const conv = getConversationByGroup(groupId);
    if (conv) {
      for (const sessionId of listSessionsByConversation(conv.conversation_id)) {
        const replay = getRunReplay(sessionId);
        if (!replay) {
          // session 记录在、事件日志已被 TTL 清理：run 列表仍可见，过程消息缺位。
          runs.push({ session_id: sessionId, status: 'idle' });
          continue;
        }
        runs.push({ session_id: sessionId, status: replay.status });
        runMessages.push(...replayTimeline(replay.events));
      }
    }

    // c) ts 升序归并。sort 稳定：同 ts 时聊天消息先于 run 消息（拼接顺序）。
    const merged = [...chatMessages, ...runMessages].sort((a, b) => a.ts - b.ts);
    const truncated = merged.length > TIMELINE_MAX_MESSAGES;
    const messages = truncated ? merged.slice(merged.length - TIMELINE_MAX_MESSAGES) : merged;

    res.json({ group_id: groupId, messages, runs, truncated });
  })().catch((e) => {
    const msg = e instanceof Error ? e.message : String(e);
    if (!res.headersSent) {
      res.status(500).json({ error: { code: 'TIMELINE_FAILED', message: msg } });
    }
  });
});

/**
 * POST /api/groups/:id/messages — intercept chat send.
 *
 * Persists the user message, returns 201 immediately (front-end已乐观更新),
 * then runs the reply fan-out in the background (replies stream back via the
 * Python SSE bus). Only `sender_kind:'user'` is intercepted for reply
 * generation; non-user writes are persisted and returned as-is.
 */
router.post('/:id/messages', (req: Request, res: Response) => {
  void (async () => {
    const groupId = req.params.id;
    const body = (req.body ?? {}) as {
      content?: string;
      sender_name?: string;
      sender_kind?: string;
      executor?: string;
      model?: string;
    };
    const senderKind = body.sender_kind ?? 'user';
    const content = typeof body.content === 'string' ? body.content : '';

    try {
      // Persist the incoming message via Python. For user messages set the
      // suppress header so Python's own bridge doesn't ALSO reply (we own it).
      const created = await pyPostMessage(
        groupId,
        {
          content,
          sender_name: body.sender_name ?? (senderKind === 'user' ? 'user' : 'agent'),
          sender_kind: senderKind,
        },
        { noDispatch: senderKind === 'user' },
      );
      res.status(201).json(created);
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      res.status(502).json({ error: { code: 'PERSIST_FAILED', message: msg } });
      return;
    }

    // Only user messages trigger an agent reply.
    if (senderKind !== 'user') return;

    // Executor selection. Priority:
    //   1. Explicit body.executor — the UI model picker's choice always wins
    //      (e.g. `byok:zhipu`, `anthropic-direct`, `cli:codex`).
    //   2. 2026-11-04 默认回退修正 — 设置页配了 enabled BYOK key 的 provider
    //      优先于 cli:claude。旧行为无脑默认 cli:claude：CLI 未登录/挂起时群聊
    //      thinking 卡永远 streaming（无超时无报错，「不能正常对话」根因之一）。
    //      改法：settings/byok 里有 enabled+key 的 provider（如 zhipu）时，
    //      默认 `byok:<id>`（key 由 resolveProviderKey 的 settings 分支解析），
    //      API 直连失败也会以 error chunk 可见地报错，不再静默卡死。
    //   3. cli:claude — 最后兜底（CLI 自带 OAuth 认证时仍是好选择）。
    const executor =
      typeof body.executor === 'string' && body.executor.trim()
        ? body.executor.trim()
        : pickDefaultExecutor();
    const model =
      typeof body.model === 'string' && body.model.trim() ? body.model.trim() : undefined;

    // Fire-and-forget; replies reach the browser via Python SSE.
    // userText 原文透传（@ 提及解析用）——persisted 记录即 content，直接用它
    // 避免 runFanout 二次反查（时序上 group.messages 已含本条）。
    // 2026-11-05 审批门 — 该群有挂起的节点审批且本条消息是明确批/拒语义 →
    // 先把决定送达（不改聊天主链路：消息照常持久化； fan-out 照常，若用户
    // 批/拒后还想派新活，这条消息本身就是新一轮）。
    tryResolveApprovalFromText(groupId, content);
    void runFanout(groupId, executor, model, req.headers, content).catch((e) => {
      // eslint-disable-next-line no-console
      console.warn('[groups-chat] fanout failed:', e);
    });
  })();
});

/**
 * POST /api/groups/:id/approvals/:nodeId — 显式审批决定（2026-11-05）。
 * body: { decision: 'approve' | 'reject' }。
 * 命中挂起 → resolve 执行器 promise（执行器会补系统留痕消息 + plan_card blocked）；
 * 未命中 → 409（已决定/超时/无此挂起）。
 */
router.post('/:id/approvals/:nodeId', (req: Request, res: Response) => {
  const groupId = req.params.id;
  const nodeId = req.params.nodeId;
  const decision = (req.body ?? {}).decision;
  if (decision !== 'approve' && decision !== 'reject') {
    res.status(400).json({
      error: { code: 'BAD_DECISION', message: "decision must be 'approve' or 'reject'" },
    });
    return;
  }
  const key = `${groupId}:${nodeId}`;
  const resolve = pendingApprovals.get(key);
  if (!resolve) {
    res.status(409).json({
      error: { code: 'NO_PENDING_APPROVAL', message: `no pending approval for node ${nodeId} in group ${groupId}` },
    });
    return;
  }
  pendingApprovals.delete(key);
  try {
    resolve(decision === 'approve' ? 'approved' : 'rejected');
  } catch { /* resolver 已 settle — 幂等 */ }
  res.json({ group_id: groupId, node_id: nodeId, decision });
});

export { router as groupsChatRouter };
export default router;

/**
 * 测试专用薄导出 — runFanout 原样透传（mention 定向派活路由行为测试用，
 * 避免为驱动 fan-out 而起真 HTTP / 真 Python）。生产代码不要调用。
 */
export const runFanoutAsync = runFanout;
